2-450', '462-472', '462-473', '462-530', '462-545', '462-551', '462-571', '462-572', '462-574', '462-575', '462-579', '462-580', '462-624', '462-641', '462-646', '462-647', '462-750', '462-792', '462-979', '462-1003', '462-1007', '462-1008', '462-1021', '462-1142', '462-1476', '462-1571', '462-1588', '462-65976', '462-71255', '462-76079', '462-83409', '462-86833', '462-95083', '462-95217', '462-95220', '462-95222') ), ui_session_flags AS ( -- Aggregate UI events to session level to prevent row duplication SELECT mri_session_id, MAX(CASE WHEN event_name = 'SRP_BP_selection_loaded' THEN 1 ELSE 0 END) as SRP_BP_selection_loaded, MAX(CASE WHEN event_name = 'SRP_BP_selected' THEN 1 ELSE 0 END) as SRP_BP_selected, MAX(CASE WHEN event_name = 'added BP names' THEN 1 ELSE 0 END) as added_BP_names, MAX(CASE WHEN event_name = 'removed BP names' THEN 1 ELSE 0 END) as removed_BP_names, MAX(CASE WHEN event_name = 'BP DP screen loaded' THEN 1 ELSE 0 END) as saw_bpdp_screen, MAX(CASE WHEN event_name = 'SRP_BP_selection_closed' THEN 1 ELSE 0 END) as SRP_BP_selection_closed FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-03-14 18:30:00' AND __time < TIMESTAMP '2026-03-31 18:30:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' AND event_name IN ('SRP_BP_selection_loaded', 'SRP_BP_selected', 'SRP_BP_selection_closed', 'BP DP screen loaded', 'added BP names', 'removed BP names') GROUP BY 1 ), sl_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-03-14 18:30:00' AND __time < TIMESTAMP '2026-03-31 18:30:00' AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-03-14 18:30:00' AND __time < TIMESTAMP '2026-03-31 18:30:00' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-03-14 18:30:00' AND __time < TIMESTAMP '2026-03-31 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT srp.month_period || ' 15 to 31' AS month_period, COALESCE(srp.os, srp.channel) AS saleschannel, srp.exp_Variant, CASE WHEN u.SRP_BP_selection_loaded = 1 THEN 'Yes' ELSE 'No' END AS SRP_BP_selection_loaded, CASE WHEN u.SRP_BP_selected = 1 THEN 'Yes' ELSE 'No' END AS Bottom_Sheet_Interacted, CASE WHEN u.added_BP_names = 1 OR u.removed_BP_names = 1 THEN 'Yes' ELSE 'No' END AS LMB_Interacted, CASE WHEN u.SRP_BP_selection_closed = 1 THEN 'Yes' ELSE 'No' END AS SRP_BP_selection_closed, COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT CASE WHEN u.saw_bpdp_screen = 1 THEN sl.mri_session_id END) AS BP_DP_screen_loaded, COUNT(DISTINCT pax.mri_session_id) AS paxload, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, SUM(conf.tin_count) AS tin FROM srp_deduped srp LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN ui_session_flags u ON srp.mri_session_id = u.mri_session_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1, 2 , 3, 4 , 5, 6, 7 ORDER BY 3 ASC, 6 DESC, 5 DESC, 4 DESC, 8 DESC
